// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address nonOwner) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner.code.length == 0);
        vm.deal(address(c), amount * 2);
        vm.prank(nonOwner);
        try c.sendMoney(address(0xdead), amount) {} catch {}
        bool reverted = false;
        vm.prank(nonOwner);
        try c.withdrawAll() {
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}
